method arrayProduct(a: array<int>, b: array<int>) returns (c: array<int> )
  requires a.Length==b.Length
  ensures c.Length==a.Length
  ensures forall i:: 0 <= i< a.Length==> a[i] * b[i]==c[i]
{
  c:= new int[a.Length];
  var i:=0;
  while i<a.Length
    invariant 0 <= i <= a.Length // candidate
    decreases a.Length - i // candidate
    invariant 0 <= i // candidate
    invariant i <= a.Length // candidate
    invariant c.Length == a.Length // candidate
    invariant forall j:: 0 <= j < i ==> a[j] * b[j] == c[j] // candidate
    invariant c.Length==a.Length // candidate
    invariant forall i:: 0 <= i< i==> a[i] * b[i]==c[i] // candidate
  {
    c[i]:=a[i]*b[i];
    i:=i+1;
  }
}

method main(n: int, k: int) returns (k_out: int)
    requires n > 0;
	requires k > n;
	ensures k_out >= 0;
{
	k_out := k;
    var j: int := 0;
    while (j < n)
      invariant 0 <= j // candidate
      invariant j <= n // candidate
      invariant k_out == k - j // candidate
      invariant k_out >= 0 // candidate
    {
        j := j + 1;
        k_out := k_out - 1;
    }
}


