    // not (or (<= 1 (+ n (+ (* (- 1) j) (* (- 1) k)))) (
    //     and (<= k (- 1)) (<= (+ n (* (- 1) j)) (- 1)))))

method Symmetric(a: array<int>) returns (flag: bool)
ensures flag == true ==> forall x :: 0 <= x < a.Length ==> a[x] == a[a.Length - x - 1]
ensures flag == false ==> exists x :: 0 <= x < a.Length && a[x] != a[a.Length - x - 1]
{
    // empty == symmetrical
    if a.Length == 0 {
        return true;
    } 

    var i:int := 0;
    while i < a.Length
      decreases a.Length - i // candidate
      invariant 0 <= i // candidate
      invariant i <= a.Length // candidate
      invariant forall j :: 0 <= j < i ==> a[j] == a[a.Length - j - 1] // candidate
    {
        if a[i] != a[a.Length - i - 1] {
            return false;
        }
        i := i + 1;
    }
    return true;
}
